"""Read-only reconciliation of compact-page diagnostic JSONL; never launches Java."""

from __future__ import annotations

from collections import Counter
import json
from pathlib import Path


KEY_FIELDS = ('target', 'namespace', 'group', 'parent', 'column', 'pageIndex')
MASK64 = (1 << 64) - 1


def histogram(values):
    return {str(key): count for key, count in sorted(Counter(values).items())}


def analyze_owner(path: Path) -> dict:
    records = [json.loads(line) for line in path.read_text().splitlines()]
    assert records and records[-1]['type'] == 'factor-page-summary', path
    summary = records[-1]
    pages = records[:-1]
    assert summary['format'] == 2 and all(p['type'] == 'factor-page' for p in pages)
    variant = summary['variant']
    assert variant in ('original', 'compact')
    base = summary['baseChargeBytes']
    payload = summary['promotionChargeBytes']
    compact = [p for p in pages if p['dense'] == 0]
    dense = [p for p in pages if p['dense'] == 1]
    before_compact = sum(summary['beforeFinalCompactOccupiedSlots'])
    before_dense = sum(summary['beforeFinalDenseOccupiedSlots'])
    before_removed = summary['pagesRetiredByNamespace'] + summary['pagesClearedBeforeFinalClose']
    charges = [(p['declaredBaseBytes'], p['declaredPromotionBytes']) for p in pages]
    declared = sum(a + b for a, b in charges)
    observed_base = sum(p['baseReservationBytesAtSnapshot'] for p in pages)
    observed_payload = sum(p['promotionReservationBytesAtSnapshot'] for p in pages)
    checks = {
        'variantChargeModel': (base, payload) == ((16_384, 0) if variant == 'original' else (512, 15_872)),
        'oneOwner': all(p['owner'] == summary['owner'] for p in pages),
        'uniqueFinalPageKeys': len({tuple(p[f] for f in KEY_FIELDS) for p in pages}) == len(pages),
        'snapshotPageCount': len(pages) == summary['snapshotExpectedPages'] == summary['snapshotPages'],
        'representationExhaustive': len(compact) + len(dense) == len(pages),
        'controlAlwaysDense': variant != 'original' or not compact,
        'allAdmittedPagesClosed': summary['pageAdmissions'] == summary['pageReleases'],
        'allPagesAccountedFor': summary['pageAdmissions'] == len(pages) + before_removed,
        'allPreFinalRemovalsCounted': before_removed == before_compact + before_dense
            == sum(summary['beforeFinalLiveReferents']),
        'baseGrantsBecomePagesOrFailedConstruction': summary['baseReservationGrants']
            == summary['pageAdmissions'] + summary['baseConstructionFailureReleases'],
        'pageAdmissionAttemptsReconcile': summary['pageAdmissionAttempts']
            == summary['baseReservationGrants'] + summary['baseReservationRefusals']
            + summary['directoryInitialRefusals'] + summary['directoryGrowthRefusals']
            + summary['directoryCapacityOverflowRefusals'],
        'baseGrantBytesExact': summary['baseBytesGranted'] == summary['baseReservationGrants'] * base,
        'baseDeclaredReleasesExact': summary['baseDeclaredBytesReleased'] == summary['pageReleases'] * base,
        'promotionAttemptsReconcile': summary['promotionAttempts']
            == summary['promotionReservationGrants'] + summary['promotionRefusals'] + summary['promotionCallFailures'],
        'observedPromotionGrantsBecomeDense': summary['promotionReservationGrants'] == summary['promotionSuccesses'],
        'promotionGrantBytesExact': summary['promotionBytesGranted']
            == summary['promotionReservationGrants'] * payload,
        'promotionDeclaredReleasesExact': summary['promotionDeclaredBytesReleased']
            == summary['promotionSuccesses'] * payload,
        'controlNeverPromotes': variant != 'original' or summary['promotionAttempts'] == 0,
        'denseLifecycleCount': len(dense) + before_dense
            == (summary['pageAdmissions'] if variant == 'original' else summary['promotionSuccesses']),
        'compactLifecycleCount': len(compact) + before_compact
            == (0 if variant == 'original' else summary['pageAdmissions'] - summary['promotionSuccesses']),
        'noPagesAfterClose': summary['liveCompactPagesAfterClose'] == summary['liveDensePagesAfterClose'] == 0,
        'baseSnapshotChargeSum': observed_base == summary['snapshotPageBaseClaimBytes'],
        'promotionSnapshotChargeSum': observed_payload == summary['snapshotPagePromotionClaimBytes'],
        'baseClaimBounds': all(0 <= p['baseReservationBytesAtSnapshot'] <= base for p in pages),
        'payloadClaimBounds': all(0 <= p['promotionReservationBytesAtSnapshot'] <= (payload if p['dense'] else 0)
                                  for p in pages),
        'declaredPageChargesExact': all(a == base and b == (payload if p['dense'] else 0)
                                        for p, (a, b) in zip(pages, charges)),
        'allocatedCellCapacityExact': all(p['allocatedCellCapacity'] == (64 if p['dense'] else 1) for p in pages),
        'weakSlotAndLiveCountBounds': all(0 <= p['liveWeakReferentsAtSnapshot'] <= p['occupiedWeakReferenceSlots']
                                          <= p['allocatedCellCapacity'] for p in pages),
        'occupiedOffsetMaskCount': all((p['occupiedOffsetMask'] & MASK64).bit_count()
                                       == p['occupiedWeakReferenceSlots'] for p in pages),
        'compactOffsetMatchesMask': all(p['occupiedWeakReferenceSlots'] == 0 or
                                       (0 <= p['inlineOffset'] < 64 and p['occupiedOffsetMask'] & MASK64
                                        == 1 << p['inlineOffset']) for p in compact),
        'denseHasNoInlineOffset': all(p['inlineOffset'] == -1 for p in dense),
        'compactFinalHistogram': summary['finalCompactOccupiedSlots']
            == [sum(p['occupiedWeakReferenceSlots'] == i for p in compact) for i in range(65)],
        'denseFinalHistogram': summary['finalDenseOccupiedSlots']
            == [sum(p['occupiedWeakReferenceSlots'] == i for p in dense) for i in range(65)],
        'liveReferentFinalHistogram': summary['finalLiveReferents']
            == [sum(p['liveWeakReferentsAtSnapshot'] == i for p in pages) for i in range(65)],
        'admissionsByTargetReconcile': sum(summary['admissionsByTarget']) == summary['pageAdmissions'],
        'factorHitsByTargetReconcile': sum(summary['factorHitsByTarget']) == summary['factorHits'],
        'blockedByTargetReconcile': sum(summary['blockedMissingPagesByTarget'])
            == summary['blockedMissingPagePublications'],
        'promotionAttemptsByTargetReconcile': sum(summary['promotionAttemptsByTarget']) == summary['promotionAttempts'],
        'promotionSuccessesByTargetReconcile': sum(summary['promotionSuccessesByTarget']) == summary['promotionSuccesses'],
        'promotionRefusalsByTargetReconcile': sum(summary['promotionRefusalsByTarget']) == summary['promotionRefusals'],
        'directoryAttemptsReconcile': summary['directoryReserveAttempts'] == summary['directoryReservationGrants']
            + summary['directoryInitialRefusals'] + summary['directoryGrowthRefusals'],
        'memoAttemptsReconcile': summary['memoReserveAttempts'] == summary['memoReservationGrants'] + summary['memoRefusals'],
        'knownClaimsDoNotExceedLedger': observed_base + observed_payload + summary['snapshotOrdinaryClaimBytes']
            + summary['snapshotDirectoryClaimBytes'] + summary['snapshotMemoClaimBytes'] <= summary['snapshotLedgerBytes'],
        'noUnexpectedConstructionFailure': summary['baseConstructionFailureReleases']
            == summary['promotionCallFailures'] == 0,
    }
    release_deltas = {}
    for name, grant_field, release_field in (
        ('base', 'baseBytesGranted', 'baseBytesObservedBeforeRelease'),
        ('promotion', 'promotionBytesGranted', 'promotionBytesObservedBeforeRelease'),
        ('directory', 'directoryBytesGranted', 'directoryBytesObservedBeforeRelease'),
        ('memo', 'memoBytesGranted', 'memoBytesObservedBeforeRelease'),
    ):
        release_deltas[name] = summary[grant_field] - summary[release_field]
        checks[name + 'ObservedReleaseDoesNotExceedGrants'] = release_deltas[name] >= 0
    targets = []
    for target, name in enumerate(summary['targetNames']):
        selected = [p for p in pages if p['target'] == target]
        parent_keys = Counter((p['namespace'], p['group'], p['parent'], p['column']) for p in selected)
        targets.append({
            'target': target, 'name': name, 'pagesInFinalTable': len(selected),
            'compactPages': sum(p['dense'] == 0 for p in selected),
            'densePages': sum(p['dense'] == 1 for p in selected),
            'occupiedWeakReferenceSlots': sum(p['occupiedWeakReferenceSlots'] for p in selected),
            'occupiedSlotHistogram': histogram(p['occupiedWeakReferenceSlots'] for p in selected),
            'liveReferentHistogram': histogram(p['liveWeakReferentsAtSnapshot'] for p in selected),
            'declaredBaseBytes': sum(p['declaredBaseBytes'] for p in selected),
            'declaredPromotionBytes': sum(p['declaredPromotionBytes'] for p in selected),
            'baseBytesAtSnapshot': sum(p['baseReservationBytesAtSnapshot'] for p in selected),
            'promotionBytesAtSnapshot': sum(p['promotionReservationBytesAtSnapshot'] for p in selected),
            'namespacePageCounts': histogram(p['namespace'] for p in selected),
            'groupPageCounts': histogram(p['group'] for p in selected),
            'pageIndexCounts': histogram(p['pageIndex'] for p in selected),
            'distinctParentIdentities': len(parent_keys),
            'pagesPerParentIdentityHistogram': histogram(parent_keys.values()),
            'admissions': summary['admissionsByTarget'][target],
            'factorHits': summary['factorHitsByTarget'][target],
            'promotionAttempts': summary['promotionAttemptsByTarget'][target],
            'promotionSuccesses': summary['promotionSuccessesByTarget'][target],
            'promotionRefusals': summary['promotionRefusalsByTarget'][target],
            'blockedMissingPagePublicationCalls': summary['blockedMissingPagesByTarget'][target],
        })
    for target in targets:
        checks['target' + str(target['target']) + 'PromotionAttemptsReconcile'] = target['promotionAttempts'] \
            == target['promotionSuccesses'] + target['promotionRefusals']
    return {
        'raw': str(path), 'summary': summary, 'checks': checks, 'allChecksPassed': all(checks.values()),
        'allGrantedBytesObservedAtExplicitRelease': all(delta == 0 for delta in release_deltas.values()),
        'grantedBytesNotObservedAtExplicitRelease': release_deltas,
        'releaseScope': 'Reservation.bytes() can be zero after earlier ledger closure. Nonzero grant-minus-observation '
            'alone is not a leak claim; inspect endpoint ledger and declared lifecycle counts.',
        'tableCoverage': 'all admitted pages' if before_removed == 0 else 'final retained pages only; earlier keys absent',
        'finalTable': {
            'compactPages': len(compact), 'densePages': len(dense), 'declaredPageBytes': declared,
            'occupiedWeakReferenceSlots': sum(p['occupiedWeakReferenceSlots'] for p in pages),
            'allocatedCellCapacity': sum(p['allocatedCellCapacity'] for p in pages),
            'logicalCellCapacity': len(pages) * 64,
            'occupiedSlotHistogram': histogram(p['occupiedWeakReferenceSlots'] for p in pages),
            'namespacePageCounts': histogram(p['namespace'] for p in pages),
        },
        'matchesProspectiveUncappedCompactGeometry': variant == 'compact' and before_removed == 0
            and len(compact) == 16_384 and len(dense) == 256 and declared == 12_582_912
            and all(p['occupiedWeakReferenceSlots'] == 1 for p in compact)
            and all(p['occupiedWeakReferenceSlots'] == 64 for p in dense),
        'targets': targets,
    }
